const fs = require('node:fs');

function readConfig(path) {
  try {
    fs.readFile(path, 'utf8', (err, data) => {
      if (err) throw err;
      return JSON.parse(data);
    });
  } catch (err) {
    console.error('Could not read config:', err.message);
    return {};
  }
}

const config = readConfig('./config.json');
console.log(config);

